int main(){int checks=0;auto check=[&](bool b,const char*m){if(!b)throw std::runtime_error(m);++checks;};try{
 std::string error;Game g;check(g.importScenario(std::filesystem::path(H3_TEST_SOURCE_ROOT)/"assets/demo/scenarios/seven-lakes-1.json",error),"Import failed");check(g.ownedHeroes().size()==1&&g.heroes.size()==6,"Starting sides or roster missing");std::array<bool,8>owners{};for(auto&[id,h]:g.heroes)owners[h.owner]=true;check(owners[0]&&owners[1]&&owners[2]&&owners[3]&&owners[4]&&owners[5],"Computer factions were collapsed into one side");check(g.resources[Gold]==20000,"Normal starting resources were not preserved");int first=g.activeHeroId;auto firstValue=g.hero;g.recruitHero();check(g.ownedHeroes().size()==1,"Occupied town gate allowed recruitment");bool left=false;for(int dy=-1;dy<=1&&!left;++dy)for(int dx=-1;dx<=1&&!left;++dx){Point p{g.hero.pos.x+dx,g.hero.pos.y+dy};if(g.canStep(g.hero.pos,p)&&!g.guardingMonster(p)&&!g.objectAt(p)){g.move(p);left=true;}}check(left,"Cannot leave starting town");auto start=g.hero.pos;int gold=g.resources[Gold];g.recruitHero();check(g.ownedHeroes().size()==2&&g.resources[Gold]==gold-2500,"Paid tavern recruitment failed");auto ids=g.ownedHeroes();int second=ids.back();auto movement=g.hero.movement;check(g.selectHero(second)&&g.hero.pos==g.town.pos,"Cannot select newly recruited hero");check(g.selectHero(first)&&g.hero.pos==start&&g.hero.movement==movement,"Hero switching lost independent position or movement");g.heroes[second].value.army[0].unit=g.hero.army[0].unit;int originalCount=armyCount(g.hero.army)+armyCount(g.heroes[second].value.army);g.transferHeroArmy(second,0,0,3);check(armyCount(g.hero.army)+armyCount(g.heroes[second].value.army)==originalCount,"Meeting created or lost soldiers");check(g.hero.army[0].count==firstValue.army[0].count-3,"Adjacent hero transfer failed");
 auto old=g.heroes;g.endDay();check(g.day==2,"Kingdom end turn failed");bool changed=false;for(auto&[id,h]:g.heroes)if(h.owner&&old.contains(id))changed|=h.value.pos!=old[id].value.pos;check(changed,"Computer heroes did not move");bool spent=false;for(int owner=1;owner<=5;++owner)spent|=g.playerResources[owner][Gold]<8500;check(spent,"Computer did not spend its own treasury");check(g.validate(),"Multihero computer turn produced invalid state");auto save=std::filesystem::temp_directory_path()/"heroesiii-kingdom-test.json";check(g.save(save,error),"Multihero save failed");Game loaded;check(loaded.load(save,error)&&loaded.toJson()==g.toJson(),"Roster, treasuries or fog failed to round trip");std::filesystem::remove(save);
 // Focused fixture: this original unguarded event stores text in guardians.message.
 auto event=g.objectById(1575);check(event&&event->type==ObjectType::MapEvent,"Original event missing");auto narrative=event->properties["guardians"].value("message",std::string{});g.hero.pos=event->pos;g.mapLevel=event->level;g.visit(event->id);auto notice=g.takeAdventureVisit();check(notice&&!narrative.empty()&&notice->message==narrative,"Localized guardians narrative field was lost or threw");check(g.scenarioRules["journal"].is_array()&&!g.scenarioRules["journal"].empty(),"Story journal did not retain event");
 // Dynamic hero body must take precedence over a permanent site underneath it.
 g.heroes[second].value.pos=g.hero.pos;g.heroes[second].level=g.mapLevel;g.syncHeroObjects();check(g.objectAt(g.hero.pos)&&g.objectAt(g.hero.pos)->id==second,"Permanent scenery hid an occupying hero from targeting");
 // Buying a boat pays the original ordinary costs, without creating free ships.
 g.hero.pos=g.town.pos;g.town.built[Shipyard]=true;std::erase_if(g.objects,[](const auto&o){return o.type==ObjectType::Boat;});g.resources[Gold]=3000;g.resources[Wood]=20;g.buyBoat();check(g.resources[Gold]==2000&&g.resources[Wood]==10,"Shipyard did not charge 1000 gold and 10 wood");int boats=std::count_if(g.objects.begin(),g.objects.end(),[](const auto&o){return o.type==ObjectType::Boat;});g.buyBoat();check(boats==std::count_if(g.objects.begin(),g.objects.end(),[](const auto&o){return o.type==ObjectType::Boat;})&&g.resources[Gold]==2000,"Occupied berth charged again or spawned another boat");
 // Focused defeat fixture: a remaining town keeps the player in the game.
 g.heroes.clear();g.activeHeroId=90000;g.hero=Hero{};g.hero.pos=g.town.pos;g.hero.army={Stack{Pikeman,1}};g.heroes[g.activeHeroId]={g.hero,0,g.mapLevel};g.syncHeroObjects();Object enemy;enemy.id=90001;enemy.type=ObjectType::EnemyHero;enemy.owner=1;enemy.pos=enemy.anchor={g.hero.pos.x+1,g.hero.pos.y};enemy.army={Stack{Marksman,100}};g.objects.push_back(enemy);g.startBattle(enemy.id);int turns=0;while(g.battle&&turns++<100)g.ai();check(!g.battle&&g.report&&!g.report->won,"Defeat fixture did not finish");check(g.result==0&&g.hasTown()&&g.activeHeroId==0,"Losing the last hero incorrectly ended a kingdom that still owns a town");g.report.reset();check(g.validate(),"Town-only state cannot be saved");g.resources[Gold]=3000;g.recruitHero();check(g.activeHeroId>0&&g.ownedHeroes().size()==1&&g.resources[Gold]==500,"Town-only player cannot pay for and select a replacement hero");
 Game patrol=Game::create();patrol.scenarioId="patrol-fixture";patrol.actingOwner=1;patrol.activeHeroId=1;patrol.heroes[1]={patrol.hero,1,0};patrol.heroes[1].patrolOrigin=patrol.hero.pos;patrol.heroes[1].patrolRadius=0;check(patrol.adventurePlan().empty(),"A zero-radius scripted hero was allowed to march");
 // A route must retain the town objective across boarding and landing.
 Game nav;nav.scenarioId="sea-route-fixture";nav.mapWidth=7;nav.mapHeight=3;nav.tiles.resize(21);for(auto&t:nav.tiles){t.seen=true;t.blocked=true;}for(int x=1;x<=6;++x){auto*t=nav.tile({x,1});t->blocked=false;t->terrain=x>=2&&x<=4?Terrain::Water:Terrain::Grass;t->originalFlags=64;}nav.activeHeroId=1;nav.hero.pos={1,1};nav.hero.army={Stack{Pikeman,10}};Object boat;boat.id=10;boat.type=ObjectType::Boat;boat.pos=boat.anchor={2,1};nav.objects.push_back(boat);Object goal;goal.id=11;goal.type=ObjectType::Town;goal.owner=1;goal.pos=goal.anchor={6,1};nav.objects.push_back(goal);int target=0;auto seaRoute=nav.adventurePlan(&target);check(nav.hero.adventureGoal==11&&seaRoute.size()==1&&Point{seaRoute.back().x,seaRoute.back().y}==Point{2,1},"Planner did not preserve a trans-sea goal while stopping at boarding");nav.move({2,1});check(nav.hero.onBoat&&nav.hero.movement==0,"Boarding did not consume remaining movement");nav.hero.movement=1500;auto sailing=nav.adventurePlan(&target);check(target==11&&!sailing.empty()&&Point{sailing.front().x,sailing.front().y}==Point{3,1},"Cross-day voyage turned back toward the departure coast");nav.move({3,1});nav.move({4,1});nav.move({5,1});check(!nav.hero.onBoat&&nav.hero.movement==0,"Landing did not leave the boat and end movement");nav.hero.movement=1500;auto last=nav.adventurePlan(&target);check(target==11&&last.size()==1&&Point{last.front().x,last.front().y}==Point{6,1},"Landing lost the original town objective");
 g.heroes[g.activeHeroId].properties["absod_id"]=123456;int identity=g.activeHeroId;g.storeHero();g.activeHeroId=0;g.syncHeroObjects();check(g.objectById(identity)&&g.objectById(identity)->properties["absod_id"]==123456,"Hero proxy recreation lost its scripted defeat identity");check(g.objectById(identity)->anchor==Point{g.heroes[identity].value.pos.x+1,g.heroes[identity].value.pos.y},"Map hero sprite anchor differs from its actionable tile");
 // Actual Seven Lakes event 4449 must respect the eight-skill cap while
 // still granting its other rewards. Existing skills can be improved at cap.
 Game reward;check(reward.importScenario(std::filesystem::path(H3_TEST_SOURCE_ROOT)/"assets/demo/scenarios/seven-lakes-1.json",error)&&reward.objectById(4449),"Original rescued-mage reward missing");reward.hero.skills.fill(0);for(int skill:{Archery,Logistics,Leadership,Mysticism,LuckSkill,FireMagic,Offense,Armorer})reward.hero.skills[skill]=1;auto rescue=reward.objectById(4449)->pos;reward.hero.pos=rescue;Game known=reward,space=reward;int beforePower=reward.hero.power,beforeTroops=armyCount(reward.hero.army);reward.visit(4449);check(reward.hero.skills[Wisdom]==0&&std::count_if(reward.hero.skills.begin(),reward.hero.skills.end(),[](int n){return n>0;})==8,"Map event granted a ninth secondary skill");check(reward.hero.power==beforePower+5&&armyCount(reward.hero.army)==beforeTroops+60&&reward.validate(),"Full skills blocked unrelated rewards or invalidated the game");known.hero.skills[Mysticism]=0;known.hero.skills[Wisdom]=1;known.visit(4449);check(known.hero.skills[Wisdom]==3&&known.validate(),"Full skill slots blocked an existing skill upgrade");space.hero.skills[Mysticism]=0;space.visit(4449);check(space.hero.skills[Wisdom]==3&&space.validate(),"A free skill slot did not accept the scripted skill");
 std::cout<<checks<<" kingdom checks passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<"Kingdom after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
